# morph: subset transaction
D=/tmp/morph/daemon-core-P8b; mkdir -p $D; S=$(date +%s)-$$; L=$D/acc-$S.log
cp daemon/daemon.go $D/0-$S.go 2>/dev/null
(
 set -e
 export NO_COLOR=1 CI=1
export GOFLAGS=-mod=vendor GOPROXY=off GOSUMDB=off GOTOOLCHAIN=local GOWORK=off GOCACHE="${GOCACHE:-/tmp/morph/go-build}" GOPATH="${GOPATH:-/tmp/morph/go}"
P=$PWD/probe/daemon-core; rm -rf $P; mkdir -p $P; trap 'rm -rf $P daemon/daemon-core_probe_test.go' EXIT
cat > $P/guard.mjs <<'MORPH_GUARD_EOF'
// Guard of a Go module: the layer rules of decks/tools/layers.json and the test-file rules. `morph plan --checks`
// inlines this file into every acceptance. Imports are read by the go tool (`go list`), never by grep: a word in a
// comment is not an import. Node's standard library only.
//   node guard.mjs src <file,file,...> [mod,mod,...]      the packages of these Go files; the module paths the card's
//                                                         Component declares (`uses`): a path or a path + "/..."
//   node guard.mjs tests <file> <min> <max> [lits.json]   one Go test file; lits = strings it must hold; it may import
//                                                         the module's packages and go.mod's direct requirements
// decks/tools/layers.json: {"layers": {"<dir>": ["<dir it may import>", ...]}, "pure": ["<dir>", ...]};
// "layers" null or the file absent → every package of the module may import every other; no package is pure.
import { execFileSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";

const bad = [];
const PURE_FORBIDDEN = ["os", "os/exec", "net", "net/http", "time", "math/rand", "math/rand/v2", "syscall", "unsafe"];
const TEST_CALL = /^func Test(?:[A-Z0-9_]\w*)?\s*\(/gm;

function modulePath() {
  const text = fs.existsSync("go.mod") ? fs.readFileSync("go.mod", "utf8") : "";
  const m = /^module\s+(\S+)/m.exec(text);
  if (!m) bad.push("guard: go.mod has no module line");
  return m ? m[1] : "";
}
function readLayers() {
  const file = "decks/tools/layers.json";
  if (!fs.existsSync(file)) return { layers: null, pure: [] };
  const doc = JSON.parse(fs.readFileSync(file, "utf8"));
  return { layers: doc.layers ?? null, pure: doc.pure ?? [] };
}
function isStd(imp) {
  return !imp.split("/")[0].includes(".");
}
function goImports(dir) {
  const out = execFileSync("go", ["list", "-e", "-f", '{{join .Imports "\\n"}}', "./" + dir], {
    encoding: "utf8", stdio: ["ignore", "pipe", "pipe"],
  });
  return out.split("\n").filter(Boolean);
}
function checkSrc(files, allowed) {
  const mod = modulePath();
  const { layers, pure } = readLayers();
  const dirs = [];
  for (const f of files) {
    const d = path.posix.dirname(f.split(path.sep).join("/"));
    if (!dirs.includes(d)) dirs.push(d);
  }
  for (const dir of dirs) {
    if (layers !== null && !(dir in layers)) {
      bad.push(`guard: ${dir} is not a package of decks/tools/layers.json (have: ${Object.keys(layers).join(", ")})`);
      continue;
    }
    for (const imp of goImports(dir)) {
      if (imp === mod || imp.startsWith(mod + "/")) {
        const target = imp === mod ? "." : imp.slice(mod.length + 1);
        if (target === dir) continue;
        if (layers !== null && !layers[dir].includes(target))
          bad.push(`guard: package ${dir} imports ${imp} (allowed: ${layers[dir].join(", ") || "none"})`);
        continue;
      }
      if (!isStd(imp)) {
        if (allowed.some((m) => imp === m || imp.startsWith(m + "/"))) continue;
        bad.push(`guard: package ${dir} imports ${imp} (the standard library ${allowed.length ? "and " + allowed.join(", ") + " " : ""}only)`);
        continue;
      }
      if (pure.includes(dir) && PURE_FORBIDDEN.includes(imp))
        bad.push(`guard: package ${dir} imports ${imp} in a pure package (no ${PURE_FORBIDDEN.join(", ")})`);
    }
  }
}
function fileImports(text) {
  const out = [];
  for (const m of text.matchAll(/^import\s+(?:[\w.]+\s+)?"([^"]+)"/gm)) out.push(m[1]);
  for (const m of text.matchAll(/^import\s*\(([\s\S]*?)^\)/gm))
    for (const line of m[1].split("\n")) {
      const s = /^\s*(?:[\w.]+\s+)?"([^"]+)"/.exec(line.replace(/\/\/.*$/, ""));
      if (s) out.push(s[1]);
    }
  return out;
}
// go.mod's direct requirements: the module paths of its `require` lines and blocks, without the
// lines marked `// indirect`. A test file may import them (a judge needs a declared module's test doubles, e.g. an
// in-memory transport); the scaffold vendored them, so the test builds offline.
function directRequires() {
  const text = fs.existsSync("go.mod") ? fs.readFileSync("go.mod", "utf8") : "";
  const out = [];
  const take = (line) => {
    if (/\/\/\s*indirect\b/.test(line)) return;
    const m = /^\s*([^\s/][^\s]*)\s+v\S+/.exec(line.replace(/\/\/.*$/, ""));
    if (m && !out.includes(m[1])) out.push(m[1]);
  };
  for (const m of text.matchAll(/^require\s*\(([\s\S]*?)^\)/gm)) for (const line of m[1].split("\n")) take(line);
  for (const m of text.matchAll(/^require\s+([^(\s].*)$/gm)) take(m[1]);
  return out;
}
function checkTest(file, min, max, lits) {
  if (!fs.existsSync(file)) { bad.push(`guard: ${file} missing`); return; }
  const text = fs.readFileSync(file, "utf8");
  const mod = modulePath();
  const requires = directRequires();
  for (const imp of fileImports(text))
    if (!isStd(imp) && !(imp === mod + "/internal/testhelp" || imp.startsWith(mod + "/")) &&
        !requires.some((r) => imp === r || imp.startsWith(r + "/")))
      bad.push(`guard: ${file} imports ${imp} (the standard library${requires.length ? ", " + mod + "/internal/testhelp, " + requires.join(", ") : " and " + mod + "/internal/testhelp"} only)`);
  const code = text.split("\n").map((l) => l.replace(/\/\/.*$/, "")).join("\n");
  for (const m of code.matchAll(/\.(Skip|Skipf|SkipNow)\(|\btesting\.Short\(/g))
    bad.push(`guard: ${file} calls ${m[1] ?? "testing.Short"} (a test runs or fails, it is never skipped)`);
  const count = (text.match(TEST_CALL) ?? []).length;
  if (count < min || count > max) bad.push(`guard: ${file} has ${count} func Test, expected ${min}..${max}`);
  for (const lit of lits) if (!text.includes(lit)) bad.push(`guard: ${file} does not mention the example literal ${JSON.stringify(lit)}`);
}

const [mode, a, b, c, d] = process.argv.slice(2);
if (mode === "src") checkSrc((a ?? "").split(",").filter(Boolean), (b ?? "").split(",").filter(Boolean));
else if (mode === "tests") checkTest(a, Number(b), Number(c), d ? JSON.parse(fs.readFileSync(d, "utf8")) : []);
else bad.push(`guard: unknown mode ${mode}`);
for (const x of bad) console.log(x);
process.exit(bad.length ? 1 : 0);
MORPH_GUARD_EOF
cat > $P/firstdiff.mjs <<'MORPH_FIRSTDIFF_EOF'
// First-difference locator of a Go module: reads a `go test` log and, for every failed comparison printed by the
// module's internal/testhelp Equal ("got:  <x>" on one line, "want: <y>" on the next, indented under the failing test's
// line), prints where the two first differ, with 40 chars of context on each side. `morph plan --checks` inlines this
// file into every acceptance.
//   node firstdiff.mjs <go test log>
import fs from "node:fs";

const lines = fs.readFileSync(process.argv[2], "utf8").split("\n");
const pairs = [];
for (let i = 0; i + 1 < lines.length; i++) {
  const got = /^\s+got:\s+(.*)$/.exec(lines[i]);
  const want = /^\s+want:\s+(.*)$/.exec(lines[i + 1]);
  if (got && want) {
    pairs.push([want[1], got[1]]);
    i++;
  }
}
let shown = 0;
for (const [e, r] of pairs) {
  if (e === r || shown >= 6) continue;
  let k = 0;
  while (k < e.length && k < r.length && e[k] === r[k]) k++;
  const at = (s) => JSON.stringify((k > 40 ? "..." : "") + s.slice(Math.max(0, k - 40), k + 40));
  console.log(`first difference at char ${k} of ${e.length}/${r.length}: expected ${at(e)} received ${at(r)}`);
  shown++;
}
MORPH_FIRSTDIFF_EOF
cat > $P/overlay.json <<'MORPH_CONF_EOF'
{"Replace":{}}
MORPH_CONF_EOF
cat > $P/full.json <<'MORPH_CONF_EOF'
{"Replace":{}}
MORPH_CONF_EOF
echo '== build'; go build -overlay $P/overlay.json ./daemon
echo '== vet'; E=0; go vet -overlay $P/overlay.json ./daemon || E=1
echo '== gofmt'; F=$(gofmt -l daemon/daemon.go 2>&1) || true; [ -z "$F" ] || { echo "gofmt -l lists: $F"; gofmt -d daemon/daemon.go 2>&1 | head -60; E=1; }
echo '== guard'; node $P/guard.mjs src daemon/daemon.go
echo '== probe'; cat > daemon/daemon-core_probe_test.go <<'MORPH_PROBE_EOF'
package daemon

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"testing"
	"time"

	"morphstudio/claude"
	"morphstudio/control"
	"morphstudio/eventlog"
	"morphstudio/github"
	"morphstudio/internal/testhelp"
	"morphstudio/queue"
	"morphstudio/registry"
	"morphstudio/runner"
	"morphstudio/stream"
	"morphstudio/supervisor"
	"morphstudio/telegram"
)

// pDCH is the harness of the Daemon Core examples: every fake the record names, guarded by one mutex.
type pDCH struct {
	t        *testing.T
	tmp      string
	state    string
	reg      *registry.Registry
	run      *runner.Fake
	mu       sync.Mutex
	launches []claude.Launch
	procs    []*claude.Fake
	posts    [][4]string
	clock    time.Time
	ids      int
	do       func(*http.Request) (*http.Response, error)
	fail     error
	doneWait time.Duration
	d        *Daemon
}

func pDCAdd(t *testing.T, reg *registry.Registry, tmp, name string) {
	t.Helper()
	dir := filepath.Join(tmp, "projects", name)
	measure, err := os.ReadFile("../tests/fixtures/git/measure.md")
	if err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(filepath.Join(dir, "docs"), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, "docs", "MEASURE.md"), measure, 0o644); err != nil {
		t.Fatal(err)
	}
	if err := reg.Add(registry.Project{Name: name, Language: "go", RepoURL: "https://github.com/acme/" + name, Dir: dir,
		Caps: queue.Caps{ClaudeUSD: 30, Hours: 3, ExecutorUSD: 5}, CreatedAt: time.Date(2026, 10, 8, 14, 0, 0, 0, time.UTC)}); err != nil {
		t.Fatal(err)
	}
}

func pDCNew(t *testing.T, names ...string) *pDCH {
	t.Helper()
	h := &pDCH{t: t, tmp: t.TempDir(), clock: time.Date(2026, 10, 8, 15, 0, 0, 0, time.UTC)}
	h.state = filepath.Join(h.tmp, "state")
	reg, err := registry.Open(h.state)
	if err != nil {
		t.Fatal(err)
	}
	h.reg = reg
	for _, n := range names {
		pDCAdd(t, reg, h.tmp, n)
	}
	h.run = &runner.Fake{Script: map[string]runner.Result{
		"git rev-parse --abbrev-ref HEAD": {Stdout: "main\n"},
		"git rev-parse HEAD":              {Stdout: "aaa111\n"},
		"git rev-parse origin/main":       {Stdout: "aaa111\n"},
		"git status --porcelain":          {Stdout: ""},
	}}
	return h
}

func (h *pDCH) deps() Deps {
	return Deps{
		Registry: h.reg,
		Runner:   h.run,
		Spawn: func(ctx context.Context, l claude.Launch) (claude.Process, error) {
			h.mu.Lock()
			defer h.mu.Unlock()
			if h.fail != nil {
				h.launches = append(h.launches, l)
				return nil, h.fail
			}
			f := claude.NewFake()
			h.launches = append(h.launches, l)
			h.procs = append(h.procs, f)
			return f, nil
		},
		Post: func(ctx context.Context, project, kind, headline, numbers string) (telegram.Status, error) {
			h.mu.Lock()
			defer h.mu.Unlock()
			h.posts = append(h.posts, [4]string{project, kind, headline, numbers})
			return telegram.Status{}, nil
		},
		GitHubDo: func(r *http.Request) (*http.Response, error) {
			h.mu.Lock()
			do := h.do
			h.mu.Unlock()
			if do == nil {
				return nil, errors.New("no network in tests")
			}
			return do(r)
		},
		Now: func() time.Time {
			h.mu.Lock()
			defer h.mu.Unlock()
			now := h.clock
			h.clock = h.clock.Add(time.Second)
			return now
		},
		NewID: func() string {
			h.mu.Lock()
			defer h.mu.Unlock()
			h.ids++
			return fmt.Sprintf("id-%d", h.ids)
		},
		Config: Config{ClaudeBin: "/opt/claude/bin/claude", MorphBin: "/usr/local/bin/morph", ProjectsDir: filepath.Join(h.tmp, "projects"),
			MCPBaseURL: "http://127.0.0.1:7181", Defaults: queue.Caps{ClaudeUSD: 25, Hours: 2, ExecutorUSD: 4}, MaxParallel: 1,
			DoneWait: h.doneWait, Loop: supervisor.Config{MaxResumesPerHour: 3, StallMinutes: 30, StretchUSD: 30, UsageAlertPercent: 50}},
	}
}

func (h *pDCH) open() *Daemon {
	h.t.Helper()
	d, err := Open(context.Background(), h.deps())
	if err != nil {
		h.t.Fatalf("Open: %v", err)
	}
	if d == nil {
		h.t.Fatalf("Open returned a nil daemon")
	}
	h.d = d
	return d
}

func (h *pDCH) spawns() ([]claude.Launch, []*claude.Fake) {
	h.mu.Lock()
	defer h.mu.Unlock()
	return append([]claude.Launch(nil), h.launches...), append([]*claude.Fake(nil), h.procs...)
}

func (h *pDCH) postList() [][4]string {
	h.mu.Lock()
	defer h.mu.Unlock()
	return append([][4]string(nil), h.posts...)
}

func (h *pDCH) setScript(key string, r runner.Result) {
	h.run.Script[key] = r
}

func pDCPlan(t *testing.T) queue.Plan {
	t.Helper()
	b, err := os.ReadFile("../tests/fixtures/plan/queue-3.json")
	if err != nil {
		t.Fatal(err)
	}
	var p queue.Plan
	if err := json.Unmarshal(b, &p); err != nil {
		t.Fatal(err)
	}
	return p
}

func pDCErr(err error) string {
	if err == nil {
		return "<nil>"
	}
	return err.Error()
}

// pDCRunning builds example 2's state: demo with P17 running.
func pDCRunning(t *testing.T) (*pDCH, *Daemon) {
	h := pDCNew(t, "demo")
	d := h.open()
	v, err := d.PlanLoad("demo", pDCPlan(t))
	if err != nil || v.State != "running" {
		t.Fatalf("setup: PlanLoad(demo) = %+v, %v; want State running", v, err)
	}
	if _, procs := h.spawns(); len(procs) != 1 {
		t.Fatalf("setup: PlanLoad(demo) spawned %d processes, want 1", len(procs))
	}
	return h, d
}

func pDCStatus(t *testing.T, d *Daemon, project string) control.Status {
	t.Helper()
	s, err := d.Status(project)
	if err != nil {
		t.Errorf("Status(%q) error %v", project, err)
	}
	return s
}

func pDCLines(t *testing.T, path string) []string {
	b, err := os.ReadFile(path)
	if err != nil {
		return []string{"read error: " + err.Error()}
	}
	return strings.Split(strings.TrimRight(string(b), "\n"), "\n")
}

func TestProbeDaemonCoreExample1(t *testing.T) {
	h := pDCNew(t, "demo")
	d := h.open()
	testhelp.Equal(t, "example 1 Projects()", d.Projects(), []control.ProjectView{{Name: "demo", Language: "go",
		RepoURL: "https://github.com/acme/demo", State: "idle", CreatedAt: time.Date(2026, 10, 8, 14, 0, 0, 0, time.UTC)}})
	s, err := d.Status("demo")
	testhelp.Equal(t, "example 1 Status(demo)", []any{s, pDCErr(err)}, []any{control.Status{State: "idle", LimitsUnknown: true}, "<nil>"})
	sj, _ := json.Marshal(s)
	testhelp.Equal(t, "example 1 json.Marshal(Status(demo)) holds the null limits", strings.Contains(string(sj), `"five_hour":null,"seven_day":null`), true)
	s, err = d.Status("nope")
	testhelp.Equal(t, "example 1 Status(nope)", []any{s, errors.Is(err, control.ErrUnknownProject)}, []any{control.Status{}, true})
	st, err := d.StopCheck("demo")
	testhelp.Equal(t, "example 1 StopCheck(demo)", []any{st == nil, pDCErr(err)}, []any{true, "<nil>"})
	u, err := d.Usage("demo")
	testhelp.Equal(t, "example 1 Usage(demo)", []any{u, pDCErr(err)}, []any{control.Usage{}, "<nil>"})
	uj, _ := json.Marshal(u)
	testhelp.Equal(t, "example 1 json.Marshal(Usage(demo))", string(uj), `{"five_hour":null,"seven_day":null,"five_hour_resets_at":null,"seven_day_resets_at":null,"session_cost_usd":0,"stretch_cost_usd":0,"limits_at":null}`)
	_, procs := h.spawns()
	testhelp.Equal(t, "example 1 no spawn at Open", len(procs), 0)
	// variant: an empty registry lists [] (not nil)
	h2 := pDCNew(t)
	testhelp.Equal(t, "example 1 variant Projects() of an empty registry", h2.open().Projects(), []control.ProjectView{})
}

func TestProbeDaemonCoreExample2(t *testing.T) {
	h := pDCNew(t, "demo")
	d := h.open()
	v, err := d.PlanLoad("demo", pDCPlan(t))
	testhelp.Equal(t, "example 2 PlanLoad(demo)", []any{v, pDCErr(err)},
		[]any{control.QueueView{State: "running", Approved: "7b31dfe", Index: 0, Phases: 3, Current: "P17"}, "<nil>"})
	launches, procs := h.spawns()
	mcp := filepath.Join(h.state, "demo", "morphd-mcp.json")
	testhelp.Equal(t, "example 2 the Spawn launches", launches, []claude.Launch{{Bin: "/opt/claude/bin/claude",
		Dir: filepath.Join(h.tmp, "projects", "demo"), SessionID: "id-1", Resume: false, BudgetUSD: 30, MCPConfigPath: mcp}})
	b, err := os.ReadFile(mcp)
	testhelp.Equal(t, "example 2 the MCP config file", string(b)+pDCErr(err),
		string(claude.MCPConfigJSON("http://127.0.0.1:7181/mcp/demo/session", "id-2"))+"<nil>")
	tok, err := h.reg.ReadSecret("demo", "session-token")
	testhelp.Equal(t, "example 2 the secret session-token", tok+" "+pDCErr(err), "id-2 <nil>")
	if len(procs) == 1 {
		testhelp.Equal(t, "example 2 fp.Written()", procs[0].Written(), [][]byte{stream.User("/morph-orchestrator P17")})
	}
	testhelp.Equal(t, "example 2 the posts", h.postList(), [][4]string{{"demo", "start", "P17 started", "session id-1 · cap $30 · 3 h"}})
	s := pDCStatus(t, d, "demo")
	testhelp.Equal(t, "example 2 Status State, Phase, SessionID", []string{s.State, s.Phase, s.SessionID}, []string{"busy", "P17", "id-1"})
	lines := pDCLines(t, filepath.Join(h.state, "demo", "sessions", "id-1.jsonl"))
	dir := ""
	if len(lines) == 1 {
		var e struct {
			Dir string `json:"dir"`
		}
		_ = json.Unmarshal([]byte(lines[0]), &e)
		dir = e.Dir
	}
	testhelp.Equal(t, "example 2 the session log lines and the first dir", []any{len(lines), dir}, []any{1, "in"})
	// variant: a project the registry does not hold
	_, err = d.PlanLoad("nope", pDCPlan(t))
	testhelp.Equal(t, "example 2 variant PlanLoad(nope) is ErrUnknownProject", errors.Is(err, control.ErrUnknownProject), true)
	// variant: a plan queue.Load refuses is ErrBadInput wrapping the queue's text
	h2 := pDCNew(t, "demo")
	_, err = h2.open().PlanLoad("demo", queue.Plan{Approved: "abc", Phases: nil})
	testhelp.Equal(t, "example 2 variant PlanLoad of a plan without phases", []any{errors.Is(err, control.ErrBadInput), pDCErr(err)},
		[]any{true, "bad input: queue: no phases"})
}

func TestProbeDaemonCoreExample3(t *testing.T) {
	h, d := pDCRunning(t)
	r, err := d.Order("demo", "smoke checked green")
	testhelp.Equal(t, "example 3 Order while the first line is in flight", []any{r.Queued, r.Sent, pDCErr(err)}, []any{1, false, "<nil>"})
	q, err := d.Pending("demo")
	testhelp.Equal(t, "example 3 Pending", []any{q == nil, pDCErr(err)}, []any{true, "<nil>"})
	err = d.Answer("demo", 1)
	testhelp.Equal(t, "example 3 Answer without a question is ErrNoQuestion", errors.Is(err, control.ErrNoQuestion), true)
	err = d.Interrupt("demo")
	testhelp.Equal(t, "example 3 Interrupt", pDCErr(err), "<nil>")
	_, procs := h.spawns()
	w := procs[0].Written()
	if testhelp.Equal(t, "example 3 the number of lines written", len(w), 2) {
		testhelp.Equal(t, "example 3 Written()[1]", string(w[1]), string(stream.Interrupt("int-id-3")))
	}
	ev, err := d.Events("demo", 0, 10)
	dirs := []string{}
	for _, e := range ev.Entries {
		dirs = append(dirs, fmt.Sprintf("%d %s", e.Seq, e.Dir))
	}
	testhelp.Equal(t, "example 3 Events", []any{dirs, ev.Last, pDCErr(err)}, []any{[]string{"1 in", "2 in"}, int64(2), "<nil>"})
	// variant: an idle project has no session
	h2 := pDCNew(t, "demo")
	d2 := h2.open()
	_, err = d2.Order("demo", "x")
	testhelp.Equal(t, "example 3 variant Order on an idle project is ErrNoSession", errors.Is(err, control.ErrNoSession), true)
	ev, err = d2.Events("demo", 0, 10)
	testhelp.Equal(t, "example 3 variant Events of a project without a log", []any{ev.Entries != nil, len(ev.Entries), ev.Last, pDCErr(err)},
		[]any{true, 0, int64(0), "<nil>"})
}

func TestProbeDaemonCoreExample4(t *testing.T) {
	h, d := pDCRunning(t)
	_, err := d.PlanLoad("demo", pDCPlan(t))
	testhelp.Equal(t, "example 4 PlanLoad while running is ErrBusy", errors.Is(err, control.ErrBusy), true)
	err = d.Restart("demo", false)
	testhelp.Equal(t, "example 4 Restart(false) on a busy machine is ErrBusy", errors.Is(err, control.ErrBusy), true)
	err = d.Restart("demo", true)
	testhelp.Equal(t, "example 4 Restart(true)", pDCErr(err), "<nil>")
