// pDCAdvance moves the harness clock forward under the same mutex as Now.
func (h *pDCH) advance(d time.Duration) {
	h.mu.Lock()
	h.clock = h.clock.Add(d)
	h.mu.Unlock()
}

func (h *pDCH) calls() []runner.Call {
	return append([]runner.Call(nil), h.run.Calls...)
}

func pDCHasCall(calls []runner.Call, line string) bool {
	for _, c := range calls {
		if runner.Key(c.Name, c.Args...) == line {
			return true
		}
	}
	return false
}

// pDCPending builds example 12's state: DoneWait 30 s, P17 running, PhaseDone held pending.
func pDCPending(t *testing.T) (*pDCH, *Daemon, *claude.Fake) {
	h := pDCNew(t, "demo")
	h.doneWait = 30 * time.Second
	d := h.open()
	v, err := d.PlanLoad("demo", pDCPlan(t))
	if err != nil || v.State != "running" {
		t.Fatalf("setup: PlanLoad(demo) = %+v, %v; want State running", v, err)
	}
	_, procs := h.spawns()
	if len(procs) != 1 {
		t.Fatalf("setup: PlanLoad(demo) spawned %d processes, want 1", len(procs))
	}
	if s := pDCStatus(t, d, "demo"); s.State != "busy" {
		t.Fatalf("setup: Status(demo).State = %q after the first line, want busy", s.State)
	}
	err = d.PhaseDone("demo", "id-2", "P17", "P18")
	testhelp.Equal(t, "example 12 PhaseDone with DoneWait 30 s and a busy machine", pDCErr(err), "<nil>")
	return h, d, procs[0]
}

