func TestProbeDaemonCoreExample12DoneWaitReady(t *testing.T) {
	// the record: a phase_done while the machine is "ready" runs the end batch at once, even with DoneWait > 0
	h := pDCNew(t, "demo")
	h.doneWait = 30 * time.Second
	d := h.open()
	if _, err := d.PlanLoad("demo", pDCPlan(t)); err != nil {
		t.Fatalf("setup: PlanLoad: %v", err)
	}
	_, procs := h.spawns()
	if len(procs) != 1 {
		t.Fatalf("setup: %d processes, want 1", len(procs))
	}
	fp := procs[0]
	for _, n := range []int{4, 5, 6, 7} {
		_, msg := testhelp.ProbeLine(t, "../tests/fixtures/stream/probe.jsonl", n)
		fp.Emit(msg)
	}
	deadline := time.Now().Add(2 * time.Second)
	for pDCStatus(t, d, "demo").State != "ready" && time.Now().Before(deadline) {
		time.Sleep(10 * time.Millisecond)
	}
	if s := pDCStatus(t, d, "demo"); s.State != "ready" {
		t.Fatalf("setup: Status(demo).State = %q after the probe's result, want ready", s.State)
	}
	err := d.PhaseDone("demo", "id-2", "P17", "P18")
	launches, _ := h.spawns()
	testhelp.Equal(t, "example 12 variant PhaseDone on a ready machine runs at once: error, Killed, spawns", []any{pDCErr(err), fp.Killed(), len(launches)}, []any{"<nil>", true, 2})
}

