func pPUWaitSpawns(t *testing.T, h *pPUH, what string, n int) []claude.Launch {
	ok, last := pPUPoll(func() (bool, string) {
		l, _ := h.spawns()
		return len(l) >= n, fmt.Sprintf("%d spawns", len(l))
	})
	if !ok {
		t.Errorf("%s poll until Spawn was called %d times: %s", what, n, last)
	}
	h.d.Wait("demo")
	l, _ := h.spawns()
	return l
}

